const r = await tools.exec_command({
  cmd: "python3 - <<'PY'
import itertools
birds = ['owl', 'crow', 'cardinal']
valid = []
for order in itertools.permutations(birds):
    pos = {bird: order.index(bird) for bird in birds}
    if pos['crow'] < pos['owl'] and pos['owl'] == 1:
        valid.append(order)
print(valid)
print('second:', {order[1] for order in valid})
PY",
  workdir: "<WORKSPACE>",
  yield_time_ms: 10000,
  max_output_tokens: 2000
});
text(r.output);

